let data;try{data=JSON.parse(localStorage.getItem('hangul-v1')||'{}')}catch{data={}}data={unit:0,stars:0,done:{},mistakes:[],days:[],minutes:0,sound:true,rate:.85,limit:30,...data};data.unit=Math.max(0,Math.min(5,Number(data.unit)||0));let state={page:'home'},session=null,ink=false,timer=null,startedAt=0;const save=()=>{try{localStorage.setItem('hangul-v1',JSON.stringify(data))}catch{}};const today=()=>new Date().toLocaleDateString('sv-SE');
function speak(text){if(!data.sound)return;window.ToriMagic?.play(text,data.rate)}
function feedback(text,error=false){const f=$('#feedback');if(f){f.textContent=text;f.className='feedback'+(error?' error':'');f.setAttribute('role','status')}}
const shuffle=a=>[...a].sort(()=>Math.random()-.5);const current=()=>units[data.unit];const completed=()=>Object.keys(data.done).filter(k=>k.startsWith(today()+':'+data.unit+':')).length;
const activities=[['소리 찾기','귀를 쫑긋! 소리를 찾아요','🔊',3,'#edf2da'],['글자 조립','소리를 모아 글자를 만들어요','🧩',7,'#f9ebce'],['한글 놀이터','낱말 보물을 찾아 떠나요','🎈',8,'#f7e3d9'],['쓰기 · 받아쓰기','내 손으로 한글을 완성해요','✏️',7,'#e7edf8'],['이야기 시간','읽고 생각하며 마무리해요','📖',5,'#eee7f5']];
function render(){window.ToriMagic?.cancel();document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===state.page));if(state.page==='home')home();if(state.page==='map')map();if(state.page==='collection')collection();window.ToriMagic?.mount()}
function home(){$('#app').innerHTML=`<div class="status"><div class="greeting"><b>안녕, 꼬마 탐험가! 👋</b><br><span class="small" style="color:var(--muted)">오늘도 토리와 한 뼘 자라 볼까요?</span></div><div class="stats"><div class="stat">탐험한 날 <b>${data.days.length}일</b></div><div class="stat">모은 별 <b>★ ${data.stars}</b></div><div class="stat">오늘의 미션 <b>${completed()}/5</b></div></div></div><section class="hero"><div class="heroText"><div class="pill">매일 30분 · 놀이로 배우는 한글</div><h1>한 글자씩 모험하고,<br>자신감은 쑥쑥!</h1><p>토리와 함께 소리를 찾고, 글자를 만들어요.<br>오늘의 작은 발견이 내일의 읽기가 될 거예요.</p><button class="primary" id="start">오늘의 탐험 시작하기　→</button></div><div class="heroArt" aria-label="토끼 친구 토리와 한글 숲"><div class="sun"></div><div class="cloud"></div><div class="hill"></div><div class="hill two"></div><div class="letter one">가</div><div class="letter two">나</div><div class="mascot"><i class="ear l"></i><i class="ear r"></i><i class="eyes"></i><i class="cheek"></i><span class="mouth">ᴗ</span><i class="scarf"></i></div><div class="speech">같이 놀자, 친구야! 🌿</div></div></section><div class="sectionHead"><h2>오늘의 탐험 코스</h2><span>${current().icon} ${current().title} · 약 30분</span></div><div class="cards">${activities.map((a,i)=>`<button class="card" data-act="${i}" style="--tint:${a[4]}"><div class="icon">${a[2]}</div><span class="step">MISSION 0${i+1} ${data.done[today()+':'+data.unit+':'+i]?'✓':''}</span><h3>${a[0]}</h3><p>${a[1]}</p><div class="time"><span>◷ ${a[3]}분</span><span>시작 →</span></div></button>`).join('')}</div><div class="lower"><div class="notice"><span class="big">🧭</span><div><h3>우리 아이에게 맞는 출발점</h3><p>짧은 놀이로 지금의 한글 실력을 알아봐요.</p></div><button id="diagnose">실력 알아보기 →</button></div><div class="notice" style="background:#eaf0e4"><span class="big">🌱</span><div><h3>틀려도 괜찮아, 배우는 중이니까!</h3><p>헷갈린 낱말은 다음 탐험에서 다시 만나요.</p></div></div></div>`;$('#start').onclick=()=>start(0,true);$('#diagnose').onclick=diagnose;document.querySelectorAll('[data-act]').forEach(b=>b.onclick=()=>start(+b.dataset.act,false))}
function map(){$('#app').innerHTML=`<div class="eyebrow">MY LEARNING JOURNEY</div><h1>한글이 자라는 배움 지도</h1><p>6개의 세계에서 듣기부터 이야기 이해까지. 단계는 언제든 바꿀 수 있어요.</p><div class="mapGrid">${units.map((u,i)=>`<div class="mapCard"><span style="font-size:40px">${u.icon}</span><h3>${i+1}. ${u.title}</h3><p>${u.sub}<br>${u.words.slice(0,3).join(' · ')}</p><span class="small">${Object.keys(data.done).filter(k=>k.split(':')[1]===String(i)).length}개 미션 완료</span><br><button class="${i===data.unit?'primary':'ghost'}" data-unit="${i}">${i===data.unit?'지금 배우는 곳':'이 단계에서 배우기'} →</button></div>`).join('')}</div>`;document.querySelectorAll('[data-unit]').forEach(b=>b.onclick=()=>{data.unit=+b.dataset.unit;save();state.page='home';render()})}
function collection(){const levels=[1,5,15,30,50,100,150,250];$('#app').innerHTML=`<div class="eyebrow">LITTLE TREASURES</div><h1>차곡차곡, 내 보물함</h1><p>노력한 만큼 별이 쌓여요. 지금까지 <b>${data.stars}개</b>의 별을 모았어요.</p><div class="badges">${['🌱','🌼','🦋','🍀','🌈','🦉','🦄','🏰'].map((x,i)=>`<div class="badge ${data.stars<levels[i]?'dim':''}"><span>${x}</span><b>${['첫걸음 씨앗','반짝 꽃','낱말 나비','용기 클로버','읽기 무지개','지혜 부엉이','꿈의 유니콘','한글의 성'][i]}</b><p class="small">${data.stars>=levels[i]?'획득했어요!':'별 '+levels[i]+'개에 만나요'}</p></div>`).join('')}</div>`}
function shell(title,body,progress=0){$('#app').innerHTML=`<div class="panel"><div class="activityTop"><button class="ghost" id="exit">← 탐험 홈</button><span>${title}</span><span id="elapsed">${session?'0:00':''}</span></div><div class="progress"><div style="width:${progress}%"></div></div>${body}</div>`;$('#exit').onclick=()=>{stop();state.page='home';render()};window.ToriMagic?.mount()}
function stop(){window.ToriMagic?.cancel();clearInterval(timer);if(startedAt){data.minutes+=Math.floor((Date.now()-startedAt)/60000);startedAt=0;save()}if(window.speechSynthesis)speechSynthesis.cancel();session=null}
function start(act,course){stop();session={act,course,index:0,correct:0,checked:false,items:[],rested:false};const u=current();session.items=act===0?shuffle(u.letters).slice(0,5):act===1?shuffle((data.unit<3?u.letters:units[1].letters)).slice(0,5):act===2?shuffle([...data.mistakes.filter(x=>u.words.includes(x)),...u.words]).slice(0,5):act===3?shuffle(u.words).slice(0,4):[u.story];startedAt=Date.now();timer=setInterval(()=>{if(!session)return;const seconds=Math.floor((Date.now()-startedAt)/1000);if($('#elapsed'))$('#elapsed').textContent=Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');if(seconds>=data.limit*60){const act=session.act;stop();shell('오늘은 여기까지',`<div class="center"><div class="rest">🌙</div><h2>열심히 탐험했어요!</h2><p>설정한 학습 시간이 되었어요. 눈과 손을 쉬게 해 주세요.<br>미션은 홈에서 다시 시작할 수 있어요.</p><button class="primary" id="restHome">홈으로</button></div>`);$('#restHome').onclick=()=>{state.page='home';render()}}},1000);question();speak(['귀를 쫑긋! 소리를 듣고 글자를 찾아보자!','자음과 모음이 만나면 어떤 글자가 될까?','숨어 있는 낱말 보물을 찾아보자!','손가락으로 쓱쓱! 멋진 글자를 써보자!','이야기 속으로 출발! 토리와 함께 읽어보자!'][act])}
function question(){window.ToriMagic?.cancel();const s=session,u=current(),item=s.items[s.index];s.checked=false;let body='';if(s.act===0||s.act===2){const pool=s.act===0?u.letters:u.words;const opts=shuffle([item,...shuffle(pool.filter(x=>x!==item)).slice(0,3)]);body=`<div class="center"><div class="eyebrow">${s.index+1} / ${s.items.length} · ${s.act===0?'소리 찾기':'낱말 보물찾기'}</div><h2 class="prompt">토리의 소리를 듣고<br>알맞은 ${s.act===0?'글자':'낱말'}를 찾아요</h2><button class="primary" id="listen">🔊 소리 듣기</button><div class="options">${opts.map(x=>`<button class="option" data-answer="${esc(x)}">${esc(x)}</button>`).join('')}</div><div class="feedback" id="feedback">준비되면 소리 듣기를 눌러 주세요.</div><button class="ghost" id="hint">작은 힌트</button></div>`}
if(s.act===1){const code=item.charCodeAt(0)-44032;const initial=['ㄱ','ㄲ','ㄴ','ㄷ','ㄸ','ㄹ','ㅁ','ㅂ','ㅃ','ㅅ','ㅆ','ㅇ','ㅈ','ㅉ','ㅊ','ㅋ','ㅌ','ㅍ','ㅎ'][Math.floor(code/588)];const vowel=['ㅏ','ㅐ','ㅑ','ㅒ','ㅓ','ㅔ','ㅕ','ㅖ','ㅗ','ㅘ','ㅙ','ㅚ','ㅛ','ㅜ','ㅝ','ㅞ','ㅟ','ㅠ','ㅡ','ㅢ','ㅣ'][Math.floor(code%588/28)];s.initial=initial;s.vowel=vowel;body=`<div class="center"><div class="eyebrow">${s.index+1} / ${s.items.length} · 글자 조립</div><h2>두 소리가 만나면 어떤 글자가 될까요?</h2><div class="target">${initial} + ${vowel}</div><button class="ghost" id="explain">🔊 소리 친구의 설명</button><div class="options">${shuffle([item,...shuffle(units[1].letters.filter(x=>x!==item)).slice(0,3)]).map(x=>`<button class="option" data-answer="${x}">${x}</button>`).join('')}</div><div class="feedback" id="feedback">자음과 모음을 합쳐서 읽어 보세요.</div></div>`}
if(s.act===3){const dict=s.index>=2;body=`<div class="center"><div class="eyebrow">${s.index+1} / ${s.items.length} · ${dict?'받아쓰기':'보고 쓰기'}</div><h2>${dict?'잘 듣고 손으로 써 보아요':'글자의 모양을 보며 따라 써요'}</h2>${dict?'':`<div class="target" style="font-size:52px">${esc(item)}</div>`}<button class="ghost" id="listen">🔊 ${dict?'문제 듣기':'읽어 주기'}</button><p class="small">${dict?'듣기 → 손글씨 → 정답 비교 순서예요.':'왼쪽에서 오른쪽으로, 위에서 아래로 써 보세요.'}</p><div class="canvasWrap">${dict?'':`<div class="guide" style="font-size:${item.length>5?40:90}px">${esc(item)}</div>`}<canvas id="writing" aria-label="손글씨 연습 공간"></canvas></div><div class="row"><button class="ghost" id="clear">다시 쓰기</button><button class="ghost" id="hint">${dict?'첫 글자 힌트':'획순 안내'}</button><button class="primary" id="compare">다 썼어요 · 정답 비교</button></div><details><summary class="small">키보드로도 받아쓰기</summary><input id="typed" class="textAnswer" aria-label="받아쓰기 답" autocomplete="off"><button class="ghost" id="checkTyped">답 확인</button></details><div class="feedback" id="feedback">손글씨는 자동 채점하지 않아요. 정답과 나란히 비교해 주세요.</div><div class="row" id="selfcheck"></div></div>`}
if(s.act===4){body=`<div class="center"><div class="eyebrow">읽고 생각해요</div><h2>토리의 작은 이야기</h2><div class="reading">${esc(u.story).replace(/\n/g,'<br>')}</div><div class="row"><button class="ghost" id="listen">🔊 이야기 듣기</button></div><h3>${u.q}</h3><div class="options">${shuffle([u.answer,...u.wrong]).map(x=>`<button class="option" style="font-size:19px" data-answer="${esc(x)}">${esc(x)}</button>`).join('')}</div><div class="feedback" id="feedback">이야기 속에서 답을 찾아보세요.</div></div>`}
shell(activities[s.act][0],body,s.index/s.items.length*100);if($('#listen'))$('#listen').onclick=()=>speak(item);if($('#explain'))$('#explain').onclick=()=>speak(`${s.initial}과 ${s.vowel}가 만나면 ${item}. ${item} 하고 읽어요.`);document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>check(b.dataset.answer,s.act===4?u.answer:item));if($('#hint'))$('#hint').onclick=()=>{feedback(s.act===3?(s.index>=2?'첫 글자는 “'+item[0]+'”예요.':'위에서 아래로, 왼쪽에서 오른쪽으로 써요. 정확한 획순은 보호자와 함께 확인해요.'):'정답의 첫 글자는 “'+item[0]+'”예요.');speak(s.act===3&&s.index>=2?item[0]:item)};if(s.act===3)setupWriting(item)}
function check(answer,target){if(session.checked)return;if(answer===target){session.checked=true;session.correct++;feedback('맞았어요! '+target+' 🌟 잘 듣고 생각했어요.');speak(['맞았어! 정말 잘했어.','우와! 한글 보물을 찾았어!','멋져! 네가 해냈어!'][Math.floor(Math.random()*3)]);window.ToriMagic?.react('success',data.sound);document.querySelectorAll('[data-answer]').forEach(b=>b.disabled=true);nextButton()}else{feedback('좋은 도전이에요! 소리를 다시 듣고 천천히 찾아볼까요?',true);if(!data.mistakes.includes(target))data.mistakes.push(target);save();speak('조금만 더 생각해 볼까? 토리가 도와줄게.');window.ToriMagic?.react('encourage',false)}}
function nextButton(){if($('#next'))return;const b=document.createElement('button');b.id='next';b.className='primary';b.textContent=session.index===session.items.length-1?'탐험 마치기 ★':'다음으로 →';b.style.cssText='display:block;margin:22px auto 0';$('.panel').append(b);b.onclick=()=>{session.index++;if(session.index>=session.items.length)finish();else question()}}
function setupWriting(item){const c=$('#writing'),ctx=c.getContext('2d');const dpr=devicePixelRatio||1;c.width=Math.round(c.getBoundingClientRect().width*dpr);c.height=250*dpr;ctx.scale(dpr,dpr);ctx.lineWidth=7;ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='#216c58';let down=false;const point=e=>{const r=c.getBoundingClientRect();return[e.clientX-r.left,e.clientY-r.top]};c.onpointerdown=e=>{down=true;ink=true;c.setPointerCapture(e.pointerId);ctx.beginPath();ctx.moveTo(...point(e));ctx.lineTo(point(e)[0]+.1,point(e)[1]+.1);ctx.stroke()};c.onpointermove=e=>{if(down){ctx.lineTo(...point(e));ctx.stroke()}};c.onpointerup=c.onpointercancel=()=>down=false;ink=false;$('#clear').onclick=()=>{ctx.clearRect(0,0,c.width,c.height);ink=false};$('#compare').onclick=()=>{if(!ink){feedback('먼저 손가락이나 펜으로 써 보세요.',true);return}feedback('정답은 “'+item+'”예요. 글자 모양과 빠진 글자가 있는지 비교해 보세요.');$('#selfcheck').innerHTML='<button class="primary" id="yes">비슷하게 썼어요 ✓</button><button class="ghost" id="again">조금 더 연습할래요</button>';$('#yes').onclick=()=>{if(session.checked)return;session.checked=true;session.correct++;nextButton()};$('#again').onclick=()=>{if(!data.mistakes.includes(item))data.mistakes.push(item);save();$('#clear').click();$('#selfcheck').innerHTML='';feedback('좋아요. 정답을 보며 한 번 더 써 보아요.')}};$('#checkTyped').onclick=()=>check($('#typed').value.trim().replace(/\s+/g,' '),item)}
function finish(){const s=session;const key=today()+':'+data.unit+':'+s.act;const fresh=!data.done[key];data.done[key]=true;if(fresh)data.stars+=3;if(!data.days.includes(today()))data.days.push(today());save();stop();shell('미션 완료',`<div class="center"><div class="rest">${activities[s.act][2]}</div><div class="eyebrow">MISSION COMPLETE</div><h1>멋진 탐험이었어요!</h1><p>${activities[s.act][0]} 미션을 마쳤어요.<br>${fresh?'노력의 별 3개를 모았어요! ★★★':'오늘 완료한 미션을 한 번 더 연습했어요.'}</p>${s.course&&s.act<4?'<p>먼 곳을 보고, 손을 쭉 펴고, 물 한 모금 마셔요.</p><button class="primary" id="continue">쉬었어요 · 다음 탐험 →</button>':'<p>오늘 배운 글자를 주변에서도 찾아보세요.</p><button class="primary" id="home">탐험 홈으로 →</button>'}</div>`,100);speak('야호! 오늘도 한 뼘 자랐어!');window.ToriMagic?.react('success',data.sound);if($('#continue'))$('#continue').onclick=()=>start(s.act+1,true);if($('#home'))$('#home').onclick=()=>{state.page='home';render()}}
function diagnose(){stop();let n=0,score=0;const qs=[{p:'소리를 듣고 글자를 찾아요',sound:'아',a:'아',o:['아','오','우']},{p:'소리를 듣고 글자를 찾아요',sound:'나',a:'나',o:['가','나','다']},{p:'소리를 듣고 낱말을 찾아요',sound:'나무',a:'나무',o:['바다','나무','모자']},{p:'소리를 듣고 글자를 찾아요',sound:'곰',a:'곰',o:['공','곰','콩']},{p:'“아이가 꽃에 물을 주어요.”\n누가 물을 주나요?',sound:'아이가 꽃에 물을 주어요. 누가 물을 주나요?',a:'아이',o:['아이','꽃','나무']}];const draw=()=>{if(n===qs.length){data.unit=Math.min(5,score);save();shell('출발점 찾기',`<div class="center"><div class="rest">🧭</div><h2>${current().title}에서 시작해 볼까요?</h2><p>5개 중 ${score}개를 찾았어요.<br>짧은 진단의 추천 결과예요. 배움 지도에서 언제든 단계를 바꿀 수 있어요.</p><button class="primary" id="go">탐험하러 가기</button></div>`,100);$('#go').onclick=()=>{state.page='home';render()};return}const q=qs[n];shell('놀이로 알아보는 출발점',`<div class="center"><p>${n+1} / 5</p><h2 class="prompt">${q.p}</h2><button class="primary" id="sound">🔊 소리 듣기</button><div class="options">${shuffle(q.o).map(x=>`<button class="option" data-d="${x}">${x}</button>`).join('')}</div><button class="ghost" id="skip">아직 잘 모르겠어요</button><p class="small">혼자 고를 수 있도록 기다려 주세요. 틀려도 괜찮아요.</p></div>`,n/5*100);$('#sound').onclick=()=>speak(q.sound);document.querySelectorAll('[data-d]').forEach(b=>b.onclick=()=>{if(b.dataset.d===q.a)score++;n++;draw()});$('#skip').onclick=()=>{n++;draw()}};draw()}
$('#parentBtn').onclick=()=>{$('#parentContent').innerHTML=`<div class="eyebrow">FOR PARENTS</div><h2>우리 아이의 배움 기록</h2><div class="parentStats">탐험한 날: ${data.days.length}일 · 모은 별: ${data.stars}개<br>누적 학습 시간: 약 ${data.minutes}분<br>현재 단계: ${current().title}<br>완료한 미션: ${Object.keys(data.done).length}개</div><h3 style="margin-top:22px">다시 만나면 좋은 글자</h3><p>${data.mistakes.length?data.mistakes.slice(-20).map(esc).join(' · '):'아직 기록이 없어요. 오답이 생기면 여기에 모여요.'}</p><label><input type="checkbox" id="soundSetting" ${data.sound?'checked':''}> 토리의 음성 켜기</label><label>음성 속도 <select id="rate"><option value="0.65">천천히</option><option value="0.85">보통</option><option value="1">빠르게</option></select></label><label>한 미션의 최대 시간 <select id="limit"><option value="10">10분</option><option value="20">20분</option><option value="30">30분</option></select></label><button class="ghost" id="testVoice">🔊 음성 확인</button><p class="small" style="margin-top:20px">각 코스의 시간은 권장 시간이며, 문항 풀이 속도에 따라 달라집니다. 완료 후 쉬었다가 다음 코스로 이동하세요.</p><p class="small">발랄한 토리의 한국어 AI 음성 파일을 사용합니다. 말할 때 입과 귀가 움직이고, 정답을 맞히면 토리가 축하해요. 실제 성우 녹음 및 자동 손글씨 채점은 포함되지 않습니다.</p><p class="small">기초 교육과정 6단계가 담긴 첫 버전입니다. 장기 학습용 콘텐츠 확장과 교육 전문가 검토가 필요합니다. 아이의 발달과 필요에 따라 함께 읽기와 보호자 지도를 병행해 주세요.</p><p class="small">학습 기록과 설정은 이 브라우저에만 저장됩니다. 손글씨와 음성 녹음은 저장하거나 서버로 전송하지 않아요. 기기를 바꾸거나 브라우저 데이터를 삭제하면 기록이 이어지지 않습니다.</p>`;$('#rate').value=String(data.rate);$('#limit').value=String(data.limit);$('#soundSetting').onchange=e=>{data.sound=e.target.checked;save()};$('#rate').onchange=e=>{data.rate=+e.target.value;save()};$('#limit').onchange=e=>{data.limit=+e.target.value;save()};$('#testVoice').onclick=()=>speak('안녕! 나는 토리야. 오늘도 즐겁게 한글을 배워 보자.');$('#parent').showModal()};document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{stop();state.page=b.dataset.nav;render()});$('.brand').onclick=e=>{e.preventDefault();stop();state.page='home';render()};window.toriWelcome=()=>speak('안녕! 나는 토리야. 오늘도 즐겁게 한글을 배워 보자.');render();
